const bsCase='欧州型・無配当、S100、K100、r0、T1年、Vol20％。d1＝0.1、d2＝−0.1、N(d1)＝0.5398278、N(d2)＝0.4601722。C＝100N(d1)−100N(d2)。';
const bsChange='同じ欧州型・無配当、S/K100、r0、T1、Vol40％。d1＝0.2、d2＝−0.2、N(d1)＝0.5792597、N(d2)＝0.4207403。C＝100N(d1)−100N(d2)。';
bs.lead='Black-Scholesモデルの式を、同じ株価・行使価格の具体例で計算する。ボラティリティを変えた場合も比較する。';
bs.goal='欧州型コールの価値を与えた正規分布値から計算し、モデルの仮定とVolの影響を説明できる。';
bs.sections[0]=S('最初に押さえる仕組み','Black-Scholesモデルは一定のボラティリティ、無裁定、連続的な取引等の仮定で欧州型オプションを評価します。無配当コールはC＝S N(d1)−K exp（−rT）N(d2)。Nは標準正規累積分布です。実際の株価上昇確率や市場価格の保証ではありません。',[['株式側','S N(d1)','株価とモデル上の重み'],['行使額側','K exp（−rT）N(d2)','将来支払を割引'],['次の具体例',bsCase,'正規分布の値もここで与える']],'想定元本、購入プレミアム、最大損失を区別します。モデルが直接求めるのは権利の理論価値であり、満期の利益ではありません。途中の価格は株価、時間、金利、Vol等で動くため、契約の種類と評価時点を固定して計算してください。');
bs.sections[1]=S('具体例を順番に計算する',bsCase,[['株式側','53.98278','100×0.5398278'],['行使額側','46.01722','金利0でPV(K)100'],['コール価値','約7.9656','差額']],'d1＝[ln(S/K)＋（r＋σ²/2）T]/（σ√T）、d2＝d1−σ√Tです。この例ではln(1)＝0、金利0なのでd1＝σ/2となります。Nの値は計算済みの表から与えているため、正規分布表を別ページで探す必要はありません。');
bs.sections[2]=S('条件を変えると何が変わるか',bsChange,[['株式側','57.92597','同じ元本・満期'],['行使額側','42.07403','N(d2)も再計算'],['コール価値','約15.8519','Vol上昇で価値増']],'Volを変えたらd1とd2、両方のNを計算し直します。満期株価の可能性の幅が大きくなり、下側は買い手が権利を使わずに済む一方、上側の受取余地が広がることが価値上昇の直感です。これは一定Vol等のモデル条件の比較であり、実際の価格や将来の利益の保証ではありません。');
bs.questions[0]=Q('基準例を計算する',bsCase,'コール価値は？','約7.9656。');
bs.questions[1]=Q('条件変更を計算する',bsChange,'Vol40％での価値は？','約15.8519。');
