// Accessible code-native diagrams: identical underlying values also appear in tables.
function chart(title,xlabel,ylabel,series,xlim,ylim,note){
 const X=x=>65+(x-xlim[0])/(xlim[1]-xlim[0])*590,Y=y=>285-(y-ylim[0])/(ylim[1]-ylim[0])*225;
 const colors=['#174c78','#bb780f','#087c70'];
 const ticks=[0,.25,.5,.75,1];
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 720 365" role="img" aria-label="${title}" style="display:block;width:100%;height:auto;background:#fff"><title>${title}</title>${ticks.map(t=>{const x=xlim[0]+t*(xlim[1]-xlim[0]),y=ylim[0]+t*(ylim[1]-ylim[0]);return `<path d="M65 ${Y(y)}H655" stroke="#dae2e8"/><text x="55" y="${Y(y)+4}" text-anchor="end" font-size="12" fill="#344b5d">${Number(y.toFixed(2))}</text><text x="${X(x)}" y="305" text-anchor="middle" font-size="12" fill="#344b5d">${Number(x.toFixed(2))}</text>`}).join('')}<path d="M65 60V285H655" fill="none" stroke="#344b5d"/>${series.map(([name,points],i)=>`<polyline points="${points.map(([x,y])=>X(x)+','+Y(y)).join(' ')}" fill="none" stroke="${colors[i]}" stroke-width="3"/>${points.map(([x,y])=>`<circle cx="${X(x)}" cy="${Y(y)}" r="3" fill="${colors[i]}"/>`).join('')}<text x="${75+i*205}" y="25" fill="${colors[i]}" font-size="14">${name}</text>`).join('')}<text x="360" y="338" text-anchor="middle" font-size="14" fill="#344b5d">${xlabel}</text><text x="65" y="47" font-size="14" fill="#344b5d">${ylabel}</text></svg>`;
 return s('図で確かめる関係',`<figure class="fp-figure"><figcaption>${title}</figcaption>${svg}</figure>`+p(note)+table('図の数値（読み上げ・検算用）',['系列','横軸','縦軸'],series.flatMap(([name,points])=>points.map(([x,y])=>[name,Number(x.toFixed(4)),Number(y.toFixed(4))]))));
}
function attach(items,n,...args){items.find(d=>d.number===n).sections.push(chart(...args));}
