attach(derivativeLectures,13,'ブルコールスプレッドの利益と損失の上限','満期株価','損益',[['K100買い・K110売り・費用5',stocks.map(x=>[x,Math.max(x-100,0)-Math.max(x-110,0)-5])]],[70,130],[-10,10],'利益上限5、損失上限5、損益分岐105。途中の早期割当や受渡、追加費用を除いた欧州型一単位ずつの満期図です。');
attach(portfolioLectures,2,'相関で変わる二資産ポートフォリオの変動性','Aの重み（％）','標準偏差（％）',[0,1].map(rho=>['相関'+rho,[0,.25,.5,.75,1].map(w=>[w*100,Math.sqrt(w*w*.2**2+(1-w)**2*.1**2+2*w*(1-w)*rho*.2*.1)*100])] ),[0,100],[0,25],'A標準偏差20％・B10％。期待リターンは描いていません。相関ゼロでは、途中の組合せがB単独より低い標準偏差になる領域もありますが、この相関が未来に保証されるわけではありません。');
attach(economicsLectures,1,'需要と供給が交わる数量60・価格20','数量Q','価格P',[['需要P＝50−Q/2',[[0,50],[20,40],[60,20],[100,0]]],['供給P＝Q/2−10',[[20,0],[60,20],[100,40]]]],[0,100],[0,50],'数量を横軸、価格を縦軸としています。交点はQ60・P20。所得や費用が変わると曲線そのものが移り、価格だけが変わると同じ曲線上を動きます。');
attach(economicsLectures,4,'独占：限界収入と限界費用の交点で数量を選ぶ','数量Q','価格・限界収入・限界費用',[['需要P＝100−Q',[[0,100],[40,60],[80,20],[100,0]]],['MR＝100−2Q',[[0,100],[40,20],[50,0]]],['MC＝20',[[0,20],[100,20]]]],[0,100],[0,100],'MR＝MCから数量40を決め、需要曲線へ戻して価格60を読みます。MRの交点の縦軸20を販売価格にしないことが重要です。');
attach(economicsLectures,14,'ISの右シフト：産出と金利がともに上がる例','産出Y','金利i（％）',[['旧IS：i＝10−Y/10',[[20,8],[60,4],[100,0]]],['新IS：i＝12−Y/10',[[20,10],[70,5],[100,2]]],['LM：i＝Y/10−2',[[20,0],[60,4],[70,5],[100,8]]]],[20,100],[0,10],'旧均衡はY60・i4、新均衡はY70・i5。LMを固定した学習モデルです。中央銀行の反応が違えば、実際の産出・金利変化も違います。');
